INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P00','Diagnóstico no concluyente','Sin clasificar','n/a','Los síntomas no coinciden lo suficiente con ninguna falla registrada.',ARRAY['Revisión por un técnico especializado.','Repetir el diagnóstico con más datos medidos.'],'Regla de cierre del sistema',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P01','Sobrecalentamiento de CPU','Hardware','alta','La CPU supera 85 °C por disipación insuficiente, pasta térmica seca o carga sostenida.',ARRAY['Limpiar disipador y ventilador de la CPU.','Reemplazar la pasta térmica.','Cerrar procesos pesados y revisar el perfil de energía.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P02','Sobrecalentamiento de GPU','Hardware','alta','La GPU supera 80 °C por falta de ventilación o carga gráfica sostenida.',ARRAY['Limpiar el polvo de la tarjeta gráfica.','Mejorar el flujo de aire de la caja.','Limitar los FPS o bajar la calidad gráfica en juegos.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P03','Acumulación de polvo','Hardware','media','El polvo acumulado bloquea el flujo de aire y los ventiladores trabajan al máximo.',ARRAY['Limpiar con aire comprimido las rejillas y ventiladores.','Limpiar filtros de polvo de la caja.','Programar una limpieza preventiva cada 6 meses.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P04','Fallo del ventilador','Hardware','alta','Ventilador detenido, con rodamiento desgastado o con cable desconectado.',ARRAY['Revisar que el ventilador gire y esté conectado a la placa.','Reemplazar el ventilador defectuoso.','No usar el equipo bajo carga hasta repararlo.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P05','Fuente de alimentación insuficiente','Hardware','media','La fuente de poder no entrega la potencia que exige el equipo bajo carga.',ARRAY['Verificar que la potencia de la fuente cubra CPU y GPU.','Probar con otra fuente certificada.','Revisar conectores de alimentación de la tarjeta gráfica.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P06','Problema de alimentación eléctrica','Hardware','media','Instalación eléctrica inestable o cable de poder defectuoso.',ARRAY['Cambiar el cable de poder.','Conectar el equipo a un regulador o UPS.','Probar el equipo en otra toma eléctrica.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P07','Memoria RAM insuficiente','Hardware','alta','La memoria RAM instalada no alcanza para las aplicaciones en uso.',ARRAY['Cerrar programas y pestañas que no use.','Ampliar la memoria RAM.','Revisar programas que consumen memoria en el administrador de tareas.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P08','Posible fallo de memoria RAM','Hardware','media','Módulo de RAM defectuoso o mal conectado que produce errores y congelamientos.',ARRAY['Ejecutar una prueba de memoria (por ejemplo, MemTest86).','Reasentar o cambiar los módulos de RAM.','Probar los módulos de uno en uno.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P09','Almacenamiento lleno','Hardware','alta','El disco tiene menos del 10 % libre y el sistema no puede trabajar con holgura.',ARRAY['Eliminar archivos y programas innecesarios.','Mover archivos a un disco externo o a la nube.','Ampliar o reemplazar el disco.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P10','Almacenamiento degradado','Hardware','media','El disco tiene sectores dañados o el sistema de archivos presenta errores.',ARRAY['Respaldar la información de inmediato.','Revisar el estado del disco (SMART y comprobación de errores).','Reemplazar el disco si los errores persisten.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P11','Alto consumo de CPU','Rendimiento y software','alta','Un proceso o programa mantiene la CPU por encima de 90 %.',ARRAY['Identificar y cerrar el proceso que más consume.','Actualizar o reinstalar el programa problemático.','Analizar el equipo con un antivirus.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P12','Alto consumo de GPU','Rendimiento y software','alta','Una aplicación gráfica mantiene la GPU por encima de 90 %.',ARRAY['Cerrar aplicaciones que usan aceleración gráfica.','Bajar la calidad gráfica o la resolución.','Actualizar el controlador gráfico.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P13','Controladores desactualizados o problemáticos','Rendimiento y software','media','Controlador gráfico desactualizado, dañado o incompatible.',ARRAY['Actualizar el controlador desde el sitio del fabricante.','Reinstalar el controlador de forma limpia.','Volver a la versión anterior si el error apareció tras actualizar.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P14','Problema de resolución o configuración gráfica','Rendimiento y software','alta','Resolución o configuración de pantalla no soportada por el monitor.',ARRAY['Ajustar la resolución y la frecuencia recomendadas.','Restablecer la configuración gráfica.','Probar el monitor con otro cable o equipo.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P15','Programas excesivos al inicio','Rendimiento y software','media','Demasiados programas se ejecutan al iniciar el sistema.',ARRAY['Desactivar programas innecesarios en el inicio.','Mantener solo antivirus y controladores esenciales.','Reiniciar y medir el tiempo de arranque.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P16','Sistema operativo lento','Rendimiento y software','baja','Sistema operativo con mantenimiento deficiente o archivos temporales acumulados.',ARRAY['Limpiar archivos temporales y caché.','Reiniciar el equipo periódicamente.','Considerar restaurar o reinstalar el sistema si persiste.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P17','Actualizaciones pendientes','Rendimiento y software','media','Actualizaciones pendientes o fallidas generan incompatibilidades.',ARRAY['Instalar las actualizaciones pendientes.','Ejecutar el solucionador de problemas de actualizaciones.','Reiniciar y reintentar la actualización.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P18','Posible malware','Rendimiento y software','alta','Software malicioso ejecutando procesos o ventanas desconocidas.',ARRAY['Ejecutar un análisis completo con antivirus actualizado.','Desinstalar programas desconocidos.','Cambiar contraseñas desde un equipo seguro.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P19','Pantallazo azul / BSOD','Rendimiento y software','alta','Error crítico del sistema (BSOD) por controladores, software o archivos dañados.',ARRAY['Anotar el código de error de la pantalla azul.','Actualizar o revertir controladores recientes.','Ejecutar la comprobación de archivos del sistema.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P20','Apagado inesperado','Rendimiento y software','baja','Apagado sin causa evidente: se descarta temperatura, carga y energía; posible fallo del sistema operativo.',ARRAY['Revisar el registro de eventos del sistema.','Actualizar el sistema operativo y los controladores.','Consultar a un técnico si se repite.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P21','Problema de monitor o cable de video','Monitor, red y periféricos','alta','Cable de video flojo, puerto defectuoso o monitor con falla.',ARRAY['Revisar y reconectar el cable de video.','Probar con otro cable o puerto.','Probar el monitor con otro equipo.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P22','Problema de conexión a Internet','Monitor, red y periféricos','alta','Falla del router, del cable, de la señal Wi‑Fi o del adaptador de red.',ARRAY['Reiniciar el router y el equipo.','Revisar cables o acercarse al punto de acceso.','Actualizar o reinstalar el controlador de red.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P23','Problema de audio','Monitor, red y periféricos','alta','Dispositivo de audio silenciado, mal seleccionado o con controlador defectuoso.',ARRAY['Verificar volumen y dispositivo de salida.','Reinstalar el controlador de audio.','Probar con otros parlantes o audífonos.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P24','Problema de teclado','Monitor, red y periféricos','alta','Teclado desconectado, con falla física o controlador deshabilitado.',ARRAY['Reconectar el teclado o cambiar de puerto USB.','Probar con otro teclado.','Reinstalar el controlador del teclado.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
INSERT INTO kb.hipotesis(codigo,nombre,categoria,confianza,causa_probable,recomendaciones,fuente,validada) VALUES ('P25','Problema de mouse o dispositivo USB','Monitor, red y periféricos','alta','Mouse o dispositivo USB con falla, puerto defectuoso o ahorro de energía USB.',ARRAY['Cambiar de puerto USB.','Probar el dispositivo en otro equipo.','Desactivar el ahorro de energía de los puertos USB.'],'Técnico de soporte (entrevista 1.6.4) y propuesta del equipo; pendiente de validación',false);
